const titles=['Java Core','Java + PostgreSQL','Spring Boot + REST','Security + Testes','Arquitetura + DevOps','Produção + Carreira'];
const descriptions=['Sintaxe, POO, Collections e Streams','Algoritmos, SQL, modelagem e transações','REST, JPA, Hibernate, DTOs e Flyway','JWT, OWASP, JUnit e integração','SOLID, Docker, CI/CD e deploy','Performance, documentação e entrevistas'];
const app=document.querySelector('#app');let state=load(),page='home',activeDay=1,filterMonth=0,filterStatus='all',query='',openMonths=new Set([1]),toastTimer=null;
const esc=x=>String(x??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;');
const icon=(n,extra='')=>`<i data-lucide="${n}" ${extra}></i>`;
function emit(){save(state);render()}
function notify(message){document.querySelector('.toast')?.remove();let el=document.createElement('div');el.className='toast';el.role='status';el.textContent=message;document.body.append(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.remove(),3100)}
function setRoute(route,day){page=route;if(day)activeDay=day;window.history.replaceState(null,'',`#${route}${route==='study'?'/'+activeDay:''}`);window.scrollTo({top:0,behavior:'instant'});render()}
function hydrateRoute(){let parts=location.hash.slice(1).split('/');page=['home','roadmap','study','progress','settings'].includes(parts[0])?parts[0]:'home';activeDay=Math.max(1,Math.min(180,Number(parts[1])||1));}
function sidebar(){let links=[['home','layout-dashboard','Visão geral'],['roadmap','map','Roadmap'],['progress','chart-no-axes-column','Meu progresso'],['settings','settings-2','Configurações']];return `<aside class="sidebar"><div class="brandwrap"><span class="brand-icon">D</span><span class="brand">devpath<span style="color:var(--red)">.</span><small>ENGINEERING JOURNEY</small></span></div><div class="side-heading">WORKSPACE</div><nav aria-label="Navegação principal">${links.map(([p,i,n])=>`<button class="side-link ${page===p||page==='study'&&p==='roadmap'?'active':''}" data-route="${p}">${icon(i)}${n}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="mini"><span class="micro">YOUR MISSION</span><div style="margin-top:10px;font-family:'Space Grotesk';font-size:1.1rem;font-weight:700">180 dias. <span class="accent">Um objetivo.</span></div><p class="subline" style="margin-top:9px">Aprenda. Construa. Evolua.</p><div class="line"></div><div style="display:flex;justify-content:space-between;font-size:.74rem;margin-bottom:9px"><span class="muted">Progresso geral</span><b>${Math.round(completed(state)/180*100)}%</b></div>${bar(completed(state)/180*100)}</div></div></aside>`}
function mobile(){return `<nav class="mobile-nav" aria-label="Navegação mobile">${[['home','house','Início'],['roadmap','list-checks','Roadmap'],['progress','chart-no-axes-column','Progresso'],['settings','settings','Ajustes']].map(([p,i,t])=>`<button class="navlink ${page===p||page==='study'&&p==='roadmap'?'active':''}" data-route="${p}" aria-label="${t}">${icon(i)}<span>${t}</span></button>`).join('')}</nav>`}
function topbar(){let name={home:'Visão geral',roadmap:'Seu roadmap',study:`Dia ${String(activeDay).padStart(3,'0')}`,progress:'Sua evolução',settings:'Configurações'};return `<header class="topbar"><div><div class="eyebrow mono">DEVPATH / WORKSPACE</div><div class="topbar-title">${name[page]}</div></div><div class="top-actions"><span class="micro" style="display:none">2027 EDITION</span><span class="avatar" aria-label="Perfil local">${esc(state.name[0]||'D').toUpperCase()}</span></div></header>`}
function bar(n){return `<div class="progress-rail" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(n)}"><div class="progress-fill" style="width:${Math.min(100,Math.max(0,n))}%"></div></div>`}
function metric(label,value,sub,ico){return `<section class="panel metric"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ico)}</span></div><div><div class="big">${value}</div><small>${sub}</small></div></section>`}
function renderHome(){const done=completed(state),m=Math.ceil(nextDay(state)/30),current=roadmap[nextDay(state)-1];let recent=Object.entries(state.progress).filter(([id,d])=>d?.done).sort((a,b)=>(b[1].completedAt||'').localeCompare(a[1].completedAt||'')).slice(0,4);
return `<div class="layout-stack"><section class="hero"><div class="micro mono">// THE JOURNEY STARTS HERE</div><h1 class="hero-title">BUILD YOUR<br><span>FUTURE.</span></h1><p>Pequenas entregas, todos os dias. Um caminho claro para se tornar Java Back-end Developer.</p><div class="hero-foot"><span class="chip">180 DAYS / 06 MONTHS</span><span class="micro">JAVA · SPRING · SQL</span></div></section><div class="metric-grid">${metric('Dias concluídos',String(done).padStart(2,'0'),`de 180 dias`,'check-circle-2')}${metric('Dias restantes',180-done,'continue evoluindo','calendar-days')}${metric('Progresso',Math.round(done/180*100)+'%','da jornada completa','trending-up')}${metric('Tempo estudado',(minutes(state)/60).toFixed(1)+'h','registrado de verdade','clock-3')}</div><section class="panel"><div class="progress-head"><div><div class="micro" style="margin-bottom:8px">YOUR PROGRESS</div><h2>O caminho até a produção.</h2></div><strong class="accent">${Math.round(done/180*100)}%</strong></div>${bar(done/180*100)}<div class="progress-foot"><span>${done} de 180 dias</span><span>${180-done} para concluir</span></div></section><div class="split"><section><div class="section-heading"><h2>Continue aprendendo</h2><button class="textlink" data-route="roadmap">Ver roadmap ${icon('arrow-up-right')}</button></div><article class="current-card"><div class="day-label">DAY ${String(current.id).padStart(3,'0')} / 180 <span style="color:#666;margin-left:7px">• ${esc(current.category.toUpperCase())}</span></div><h3 class="current-title">${esc(current.title)}</h3><p>${esc(current.objective)}</p><div class="current-foot"><div class="tag">${icon('clock-3')} 2h30 estimadas</div><button class="btn" data-day="${current.id}">${done===180?'REVISAR':'COMEÇAR AGORA'} ${icon('arrow-right')}</button></div></article></section><section class="panel"><div class="section-heading"><h3>Os seis módulos</h3><button class="textlink" data-route="roadmap">Explorar</button></div>${titles.map((title,i)=>`<div class="module-mini"><div class="module-number">0${i+1}</div><div class="grow"><strong>${title}</strong><small>${descriptions[i]}</small></div><span class="n">${monthCompleted(state,i+1)}/30</span></div>`).join('')}</section></div><div class="split"><section class="panel"><div class="section-heading"><h3>Consistência semanal</h3><span class="tag red">${icon('flame')} ${streak(state)} dias seguidos</span></div><p class="subline">Você registrou estudos em ${dayCountThisWeek(state)} dia(s) nesta semana. Sua meta é ${state.goal}.</p><div class="line"></div>${bar(Math.min(100,dayCountThisWeek(state)/state.goal*100))}<div class="progress-foot"><span>Meta semanal</span><b>${dayCountThisWeek(state)} / ${state.goal}</b></div></section><section class="panel"><div class="section-heading"><h3>Conquistas recentes</h3></div>${recent.length?recent.map(([id,st])=>`<div class="recent"><span class="recent-icon">${icon('check-circle-2')}</span><span class="grow"><strong>Dia ${String(id).padStart(3,'0')} · ${esc(roadmap[Number(id)-1].title)}</strong><small>${st.completedAt?new Date(st.completedAt).toLocaleDateString('pt-BR'):'Concluído'}</small></span><button data-day="${id}" class="icon-btn" aria-label="Abrir dia ${id}">${icon('arrow-up-right')}</button></div>`).join(''):`<div class="empty">${icon('sparkles')}<h3>Seu primeiro marco está próximo</h3><p>Conclua um dia e ele aparecerá aqui.</p></div>`}</section></div></div>`}
function status(d){const s=dayState(state,d.id);return s.done?'completed':s.checks?.some(Boolean)?'started':'new'}
function renderRoadmap(){let days=roadmap.filter(d=>(!filterMonth||d.month===filterMonth)&&(filterStatus==='all'||(filterStatus==='completed'&&status(d)==='completed')||(filterStatus==='pending'&&status(d)!=='completed'))&&(`${d.title} ${d.category} ${d.objective}`).toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));const grouped=[1,2,3,4,5,6].map(m=>({m,days:days.filter(d=>d.month===m)})).filter(x=>x.days.length);
return `<div class="page-intro"><span class="micro mono accent">// THE LEARNING PATH</span><h1>180 dias. <span class="accent">Um plano.</span></h1><p>Seis módulos progressivos. Escolha um tópico, pratique e registre sua evolução.</p></div><div class="searchrow"><input id="search" class="field" placeholder="Buscar tópico, tecnologia, conceito..." value="${esc(query)}" aria-label="Pesquisar aulas"/><select id="monthFilter" class="field" aria-label="Filtrar por mês"><option value="0">Todos os meses</option>${titles.map((t,i)=>`<option value="${i+1}" ${filterMonth===i+1?'selected':''}>Mês 0${i+1} · ${t}</option>`).join('')}</select></div><div class="filterbox" aria-label="Filtro de conclusão">${[['all','Todos'],['pending','Pendentes'],['completed','Concluídos']].map(([v,t])=>`<button class="filter ${filterStatus===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div><div style="margin:7px 0 17px" class="micro">${days.length} AULAS ENCONTRADAS</div>${grouped.length?grouped.map(({m,days:ds})=>`<section class="month"><button class="month-btn" data-month="${m}" aria-expanded="${openMonths.has(m)}"><div class="month-marker">0${m}</div><div class="month-info"><strong>${titles[m-1]}</strong><small>${descriptions[m-1]}</small></div><div class="month-side"><span class="percentage">${monthCompleted(state,m)}/30</span>${icon(openMonths.has(m)?'chevron-up':'chevron-down')}</div></button>${openMonths.has(m)?`<div class="month-content">${bar(monthCompleted(state,m)/30*100)}<div style="height:14px"></div>${ds.map(d=>{let st=status(d);return `<button class="day-row" data-day="${d.id}"><span class="day-n">${String(d.id).padStart(3,'0')}</span><span class="day-details"><strong>${esc(d.title)}</strong><small>${d.isReview?'Revisão / checkpoint':'2h30 · Exercício prático'}</small></span><span class="state-icon ${st==='completed'?'done':st==='started'?'started':''}">${icon(st==='completed'?'check-circle-2':st==='started'?'circle-dot':'circle')}</span></button>`}).join('')}</div>`:''}</section>`).join(''):`<section class="panel empty">${icon('search-x')}<h3>Nenhuma aula encontrada</h3><p>Tente outro termo ou remova os filtros.</p><button class="btn ghost" style="margin-top:17px" id="clearFilters">Limpar filtros</button></section>`}`}
function renderStudy(){let d=roadmap[activeDay-1],st=dayState(state,activeDay);return `<div class="study-shell"><button class="back" data-route="roadmap">${icon('arrow-left')} Voltar ao roadmap</button><section class="study-hero"><div class="day-label">DAY ${String(d.id).padStart(3,'0')} / 180 <span style="color:#9b7176">· MONTH ${String(d.month).padStart(2,'0')}</span></div><h1>${esc(d.title)}</h1><p>${esc(d.objective)}</p><div class="study-tags"><span class="tag red">${esc(d.category)}</span><span class="tag">${icon('clock-3')} 2h30 previstas</span><span class="tag ${st.done?'green':''}">${st.done?'CONCLUÍDO':st.checks?.some(Boolean)?'EM ANDAMENTO':'NÃO INICIADO'}</span></div></section><section class="panel study-section"><h3>${icon('target')} Objetivo e contexto</h3><p>${esc(d.objective)}</p></section><section class="panel study-section"><h3>${icon('code-2')} Desafio hands-on</h3><p>${esc(d.exercise)}</p></section><section class="panel study-section"><h3>${icon('layers-3')} Evidência de engenharia</h3><p>${esc(d.evidence)}</p></section><section class="panel study-section"><h3>${icon('play-circle')} Vídeo e materiais</h3>${d.resources.map(r=>`<a class="resource" href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"><span class="tag red">${icon('youtube')}</span><span class="resource-text"><strong>Pesquisar aula: ${esc(d.title)}</strong><small>Pesquisa no YouTube · vídeo individual não verificado</small></span>${icon('external-link')}</a>`).join('')}<p class="source-hint">Conteúdo da aula importado do roadmap original; recursos de vídeo são links de pesquisa, não curadoria individual.</p></section><section class="panel study-section"><div class="section-heading"><h3>${icon('list-checks')} Definition of Done</h3><span class="tag">${(st.checks||[]).filter(Boolean).length} / ${d.completionCriteria.length}</span></div><div class="checks">${d.completionCriteria.map((c,i)=>`<label class="check"><input type="checkbox" data-check="${i}" ${st.checks?.[i]?'checked':''}/><span>${esc(c)}</span></label>`).join('')}</div><div class="line"></div><div class="study-actions"><button class="btn ${st.done?'outline':''}" id="completeDay">${icon(st.done?'rotate-ccw':'check-circle-2')} ${st.done?'Desfazer conclusão':'Marcar dia como concluído'}</button></div></section><section class="panel study-section"><h3>${icon('notebook-pen')} Minhas anotações</h3><p style="margin-bottom:14px">Registre aprendizados, dificuldades, comandos e insights.</p><textarea id="dayNotes" class="field textarea" placeholder="O que aprendi hoje? O que preciso revisar?">${esc(state.notes[d.id]||'')}</textarea><p class="source-hint" id="saveIndicator">Salvamento automático neste navegador.</p></section><section class="panel study-section"><h3>${icon('timer')} Registrar tempo estudado</h3><p style="margin-bottom:14px">Registre apenas o tempo efetivamente estudado; ele será somado às suas estatísticas.</p><div class="session-row"><input id="sessionMinutes" class="field" type="number" min="1" max="1440" value="30" aria-label="Minutos estudados"/><span class="muted" style="font-size:.78rem">minutos</span><button id="addSession" class="btn ghost">${icon('plus')} Registrar sessão</button></div></section><div class="study-nav"><button class="btn ghost" data-day="${Math.max(1,d.id-1)}" ${d.id===1?'disabled':''}>${icon('arrow-left')} Anterior</button><button class="btn ghost" data-day="${Math.min(180,d.id+1)}" ${d.id===180?'disabled':''}>Próximo ${icon('arrow-right')}</button></div></div>`}
function renderProgress(){let done=completed(state);let count=new Map();for(let s of state.sessions)count.set(s.date,(count.get(s.date)||0)+s.minutes);let cells=[];for(let i=83;i>=0;i--){let day=new Date();day.setDate(day.getDate()-i);let val=count.get(localDate(day))||0;cells.push(`<div class="calcell ${val>=90?'more':val?'on':''}" title="${localDate(day)}: ${val} minutos" aria-label="${localDate(day)}: ${val} minutos"></div>`)}return `<div class="page-intro"><span class="micro mono accent">// YOUR GROWTH</span><h1>Resultados que <span class="accent">importam.</span></h1><p>Seu progresso é baseado em entregas concluídas e sessões de estudo registradas.</p></div><div class="layout-stack"><div class="metric-grid">${metric('Dias concluídos',done,'de 180 dias','check-circle-2')}${metric('Horas estudadas',(minutes(state)/60).toFixed(1)+'h','tempo registrado','clock-3')}${metric('Sequência atual',streak(state)+'d','dias com estudo','flame')}${metric('Meta da semana',dayCountThisWeek(state)+'/'+state.goal,'dias com estudo','target')}</div><section class="panel"><div class="section-heading"><h2>Progresso por módulo</h2><span class="tag red">${Math.round(done/180*100)}% TOTAL</span></div>${titles.map((t,i)=>`<div class="chartbar"><span class="name">Mês 0${i+1}</span><div class="rail"><div class="fill" style="width:${monthCompleted(state,i+1)/30*100}%"></div></div><span class="count">${monthCompleted(state,i+1)}/30</span></div><p class="subline" style="margin:0 0 13px 116px">${t}</p>`).join('')}</section><div class="split"><section class="panel"><div class="section-heading"><h3>Atividade recente</h3><span class="micro">12 SEMANAS</span></div><div class="calendar" aria-label="Calendário de atividade das últimas 12 semanas">${cells.join('')}</div><div class="callegend"><span>Sem estudo</span><span class="calcell" style="width:15px;min-height:15px"></span><span class="calcell on" style="width:15px;min-height:15px"></span><span class="calcell more" style="width:15px;min-height:15px"></span><span>90+ min</span></div></section><section class="panel"><div class="section-heading"><h3>Seu compromisso</h3></div><div style="font-family:'Space Grotesk';font-size:2.5rem;font-weight:700">${Math.round(dayCountThisWeek(state)/state.goal*100)}<span class="accent">%</span></div><p class="subline" style="margin:8px 0 17px">Meta semanal de ${state.goal} dias com estudo registrado.</p>${bar(Math.min(100,dayCountThisWeek(state)/state.goal*100))}<div class="line"></div><p class="note">Dica: o streak depende da data das sessões, não da numeração dos dias do roadmap.</p></section></div></div>`}
function renderSettings(){return `<div class="page-intro"><span class="micro mono accent">// YOUR WORKSPACE</span><h1>Do seu <span class="accent">jeito.</span></h1><p>Personalize suas metas e proteja seu progresso com backups locais.</p></div><div class="form-layout"><section class="panel"><h3 style="margin-bottom:22px">Preferências de estudo</h3><form id="settingsForm"><label class="form-label" for="userName">Como quer ser chamado?</label><input class="field" id="userName" maxlength="50" value="${esc(state.name)}" style="margin-bottom:19px"/><label class="form-label" for="studyGoal">Meta de dias de estudo por semana</label><select class="field" id="studyGoal" style="margin-bottom:19px">${[1,2,3,4,5,6,7].map(n=>`<option value="${n}" ${n===state.goal?'selected':''}>${n} ${n===1?'dia':'dias'} por semana</option>`).join('')}</select><label class="form-label" for="startDate">Data de início (opcional)</label><input class="field" id="startDate" type="date" value="${esc(state.startDate)}" style="margin-bottom:21px"/><button class="btn" type="submit">${icon('save')} Salvar preferências</button></form></section><section class="panel"><h3 style="margin-bottom:13px">Backup e segurança</h3><p class="note" style="margin-bottom:20px">Seus dados ficam exclusivamente neste navegador. A Vercel hospeda o site, mas não sincroniza seu progresso entre dispositivos. Exporte backups regularmente.</p><div class="settings-actions"><button class="btn ghost" id="exportBackup">${icon('download')} Exportar JSON</button><button class="btn ghost" id="importBackup">${icon('upload')} Importar JSON</button><input id="fileBackup" type="file" accept=".json,application/json" hidden/></div><div class="line"></div><h3 style="margin-bottom:9px">Zona de perigo</h3><p class="note" style="margin-bottom:15px">Apagar dados é irreversível sem um backup.</p><button class="btn danger" id="resetData">${icon('trash-2')} Apagar meu progresso</button></section><section class="panel"><span class="micro">DEVPATH · V1.0</span><p class="note" style="margin-top:12px">HTML + CSS + JavaScript · Design acessível · Vite · Implantação estática na Vercel · Conteúdo importado do Roadmap Java Back-end 180 dias.</p></section></div>`}
function render(){app.innerHTML=`<div class="app">${sidebar()}<main class="workspace" id="main">${topbar()}${page==='home'?renderHome():page==='roadmap'?renderRoadmap():page==='study'?renderStudy():page==='progress'?renderProgress():renderSettings()}</main></div>${mobile()}`;createIcons();bind()}
function bind(){document.querySelectorAll('[data-route]').forEach(e=>e.addEventListener('click',()=>setRoute(e.dataset.route)));document.querySelectorAll('[data-day]').forEach(e=>e.addEventListener('click',()=>setRoute('study',Number(e.dataset.day))));document.querySelectorAll('[data-month]').forEach(e=>e.addEventListener('click',()=>{let n=Number(e.dataset.month);openMonths.has(n)?openMonths.delete(n):openMonths.add(n);render()}));document.querySelectorAll('[data-filter]').forEach(e=>e.addEventListener('click',()=>{filterStatus=e.dataset.filter;render()}));document.querySelector('#search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;query=e.target.value;render();let el=document.querySelector('#search');el.focus();el.setSelectionRange(pos,pos)});document.querySelector('#monthFilter')?.addEventListener('change',e=>{filterMonth=Number(e.target.value);if(filterMonth)openMonths.add(filterMonth);render()});document.querySelector('#clearFilters')?.addEventListener('click',()=>{query='';filterMonth=0;filterStatus='all';render()});document.querySelectorAll('[data-check]').forEach(e=>e.addEventListener('change',()=>{let d=dayState(state,activeDay),checks=[...(d.checks||[])];checks[Number(e.dataset.check)]=e.target.checked;state.progress[activeDay]={...d,checks};emit()}));document.querySelector('#completeDay')?.addEventListener('click',()=>{let d=dayState(state,activeDay);if(!d.done&&(!d.checks||d.checks.filter(Boolean).length<4)&&!confirm('Alguns critérios ainda não foram marcados. Deseja concluir este dia mesmo assim?'))return;state.progress[activeDay]={...d,done:!d.done,completedAt:!d.done?new Date().toISOString():null};let done=state.progress[activeDay].done;emit();notify(done?'Dia concluído! Mais um passo na sua jornada.':'Conclusão desfeita. Você pode retomar quando quiser.')});let note=document.querySelector('#dayNotes');note?.addEventListener('input',e=>{state.notes[activeDay]=e.target.value;save(state);document.querySelector('#saveIndicator').textContent='Anotação salva automaticamente ✓'});document.querySelector('#addSession')?.addEventListener('click',()=>{let n=Number(document.querySelector('#sessionMinutes').value);if(!Number.isInteger(n)||n<1||n>1440){notify('Informe entre 1 e 1440 minutos.');return}state.sessions.push({id:crypto.randomUUID(),day:activeDay,minutes:n,date:localDate()});emit();notify(`${n} minutos registrados com sucesso.`)});document.querySelector('#settingsForm')?.addEventListener('submit',e=>{e.preventDefault();state.name=document.querySelector('#userName').value.trim().slice(0,50)||'Dev';state.goal=Number(document.querySelector('#studyGoal').value);state.startDate=document.querySelector('#startDate').value;emit();notify('Preferências salvas.')});document.querySelector('#exportBackup')?.addEventListener('click',()=>{let blob=new Blob([backup(state)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`devpath-backup-${localDate()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup exportado.')});document.querySelector('#importBackup')?.addEventListener('click',()=>document.querySelector('#fileBackup').click());document.querySelector('#fileBackup')?.addEventListener('change',async e=>{let file=e.target.files[0];if(!file)return;try{if(file.size>3_000_000)throw Error('Arquivo muito grande.');let next=parseBackup(await file.text());if(!confirm('Substituir todos os dados atuais pelos dados do backup?'))return;state=next;emit();notify('Backup importado com sucesso.')}catch(err){notify(err.message||'Não foi possível ler o arquivo.')}});document.querySelector('#resetData')?.addEventListener('click',()=>{if(!confirm('Apagar TODO seu progresso, notas e sessões? Esta ação não pode ser desfeita.'))return;if(!confirm('Confirmação final: apagar os dados deste navegador?'))return;localStorage.removeItem(KEY);state=load();setRoute('home');notify('Dados locais apagados.')})}
window.addEventListener('hashchange',()=>{hydrateRoute();render()});hydrateRoute();render();
